package app.revanced.extension.youtube.shared;
public enum PlayerType{NONE,HIDDEN,WATCH_WHILE_MINIMIZED,WATCH_WHILE_MAXIMIZED,WATCH_WHILE_FULLSCREEN,WATCH_WHILE_SLIDING_MAXIMIZED_FULLSCREEN,WATCH_WHILE_SLIDING_MINIMIZED_MAXIMIZED,WATCH_WHILE_SLIDING_MINIMIZED_DISMISSED,WATCH_WHILE_SLIDING_FULLSCREEN_DISMISSED,INLINE_MINIMAL,VIRTUAL_REALITY_FULLSCREEN,WATCH_WHILE_PICTURE_IN_PICTURE;private static volatile PlayerType current=NONE;private static final Event<PlayerType> event=new Event<>();public static PlayerType getCurrent(){return current;}public static void setFromString(String value){PlayerType next=valueOf(value);if(next!=current){current=next;event.invoke(next);}}public static Event<PlayerType> getOnChange(){return event;}public boolean isNoneOrHidden(){return this == NONE || this == HIDDEN;}public boolean isNoneHiddenOrSlidingMinimized(){return isNoneOrHidden() || this == WATCH_WHILE_SLIDING_MINIMIZED_DISMISSED;}public boolean isNoneHiddenOrMinimized(){return isNoneHiddenOrSlidingMinimized() || this == WATCH_WHILE_MINIMIZED;}public boolean isMaximizedOrFullscreen(){return this == WATCH_WHILE_MAXIMIZED || this == WATCH_WHILE_FULLSCREEN;}}
